47: // This function unwraps the application-provided surface handle into the ICD-specific surface handle
48: // corresponding to the specified physical device. If the ICD-specific surface handle does not exist
49: // yet, then this function also creates of the ICD-specific surface object. This enables lazy creation
50: // of ICD-specific surface objects and therefore avoids creating surfaces for ICDs that may not be able
51: // to or should not create the specific type of surface (one example is the VK_KHR_display extension
52: // where the VkDisplayModeKHR handles the surfaces are created from are physical-device-specific
53: // non-dispatchable handles and therefore they should not be passed down to a foreign ICD).
54: VkResult wsi_unwrap_icd_surface(struct loader_icd_term *icd_term, VkSurfaceKHR *surface) {
55:     VkIcdSurface *icd_surface = (VkIcdSurface *)(uintptr_t)(*surface);
56: 
57: #if defined(VK_USE_PLATFORM_ANDROID_KHR)
58:     if (icd_surface->base.platform == VK_ICD_WSI_PLATFORM_ANDROID) {
59:         // Android does not use ICD-created surfaces
60:         // NOTE: This may be incorrect and in fact the legacy code could result in out-of-bounds
61:         // accesses to VkIcdSurface::surface_index in case of Android, but we preserved the legacy
62:         // behavior (while also eliminating the chance for out-of-bounds accesses).
63:         return VK_SUCCESS;
64:     }
65: #endif  // VK_USE_PLATFORM_ANDROID_KHR
66: #if defined(VK_USE_PLATFORM_MACOS_MVK)
67:     if (icd_surface->base.platform == VK_ICD_WSI_PLATFORM_IOS) {
68:         // iOS does not use ICD-created surfaces (matching legacy behavior)
69:         // NOTE: This may be incorrect and in fact the legacy code could result in out-of-bounds
70:         // accesses to VkIcdSurface::surface_index in case of Android, but we preserved the legacy
71:         // behavior (while also eliminating the chance for out-of-bounds accesses).
72:         return VK_SUCCESS;
73:     }
74: #endif  // VK_USE_PLATFORM_MACOS_MVK
75: 
76:     if (NULL == icd_term->surface_list.list ||
77:         icd_term->surface_list.capacity <= icd_surface->surface_index * sizeof(VkSurfaceKHR)) {
78:         // This surface handle is not one that was created by the loader, therefore we simply return
79:         // the input surface handle unmodified. This matches legacy behavior.
80:         return VK_SUCCESS;
81:     }
82: 
83:     VkResult result = VK_SUCCESS;
84:     if (icd_term->scanned_icd->interface_version >= ICD_VER_SUPPORTS_ICD_SURFACE_KHR) {
85:         VkAllocationCallbacks *pAllocator = icd_surface->callbacks_valid ? &icd_surface->callbacks : NULL;
86:         if (VK_NULL_HANDLE == icd_term->surface_list.list[icd_surface->surface_index]) {
