95:                             &icd_term->surface_list.list[icd_surface->surface_index]);
96:                     } else {
97:                         result = VK_ERROR_EXTENSION_NOT_PRESENT;
98:                     }
99:                     break;
100: #endif  // VK_USE_PLATFORM_WAYLAND_KHR
101: 
102: #if defined(VK_USE_PLATFORM_WIN32_KHR)
103:                 case VK_ICD_WSI_PLATFORM_WIN32:
