264: // Linux WSI surface extensions are not always compiled into the loader. (Assume
265: // for Windows the KHR_win32_surface is always compiled into loader). A given
266: // Linux build environment might not have the headers required for building one
267: // of the three extensions  (Xlib, Xcb, Wayland).  Thus, need to check if
268: // the built loader actually supports the particular Linux surface extension.
269: // If not supported by the built loader it will not be included in the list of
270: // enumerated instance extensions.  This solves the issue where an ICD or layer
271: // advertises support for a given Linux surface extension but the loader was not
272: // built to support the extension.
273: bool wsi_unsupported_instance_extension(const VkExtensionProperties *ext_prop) {
274: #if !defined(VK_USE_PLATFORM_WAYLAND_KHR)
275:     if (!strcmp(ext_prop->extensionName, "VK_KHR_wayland_surface")) return true;
276: #endif  // VK_USE_PLATFORM_WAYLAND_KHR
277: #if !defined(VK_USE_PLATFORM_XCB_KHR)
278:     if (!strcmp(ext_prop->extensionName, "VK_KHR_xcb_surface")) return true;
279: #endif  // VK_USE_PLATFORM_XCB_KHR
280: #if !defined(VK_USE_PLATFORM_XLIB_KHR)
281:     if (!strcmp(ext_prop->extensionName, "VK_KHR_xlib_surface")) return true;
282: #endif  // VK_USE_PLATFORM_XLIB_KHR
283: #if !defined(VK_USE_PLATFORM_DIRECTFB_EXT)
284:     if (!strcmp(ext_prop->extensionName, "VK_EXT_directfb_surface")) return true;
285: #endif  // VK_USE_PLATFORM_DIRECTFB_EXT
286: #if !defined(VK_USE_PLATFORM_SCREEN_QNX)
287:     if (!strcmp(ext_prop->extensionName, "VK_QNX_screen_surface")) return true;
288: #endif  // VK_USE_PLATFORM_SCREEN_QNX
289: 
290:     return false;
291: }
