731: VkResult copy_surface_create_info(struct loader_instance *loader_inst, VkIcdSurface *icd_surface, const void *create_info,
732:                                   size_t struct_type_info_count, const struct loader_struct_type_info *struct_type_info,
733:                                   const char *base_struct_name, const VkAllocationCallbacks *pAllocator) {
734:     size_t create_info_total_size = 0;
735:     const void *pnext = create_info;
736:     while (NULL != pnext) {
737:         VkBaseInStructure base = {0};
738:         memcpy(&base, pnext, sizeof(VkBaseInStructure));
739:         bool known_struct = false;
740:         for (size_t i = 0; i < struct_type_info_count; ++i) {
741:             if (base.sType == struct_type_info[i].stype) {
742:                 create_info_total_size += loader_aligned_size(struct_type_info[i].size);
743:                 pnext = base.pNext;
744:                 known_struct = true;
745:                 break;
746:             }
747:         }
748:         if (!known_struct) {
749:             loader_log(loader_inst, VULKAN_LOADER_ERROR_BIT, 0, "Unsupported extension structure in %s pNext chain.",
750:                        base_struct_name);
751:             return VK_ERROR_EXTENSION_NOT_PRESENT;
752:         }
753:     }
754: 
755:     icd_surface->create_info = loader_instance_heap_alloc(loader_inst, create_info_total_size, VK_SYSTEM_ALLOCATION_SCOPE_OBJECT);
756:     if (NULL == icd_surface->create_info) {
757:         return VK_ERROR_OUT_OF_HOST_MEMORY;
758:     }
759: 
760:     uint8_t *dst = (uint8_t *)icd_surface->create_info;
761:     VkBaseInStructure *prev_struct = NULL;
762:     pnext = create_info;
763:     while (NULL != pnext) {
764:         VkBaseInStructure base = {0};
765:         memcpy(&base, pnext, sizeof(VkBaseInStructure));
766:         for (size_t i = 0; i < struct_type_info_count; ++i) {
767:             if (base.sType == struct_type_info[i].stype) {
768:                 memcpy(dst, pnext, struct_type_info[i].size);
769:                 if (NULL != prev_struct) {
770:                     prev_struct->pNext = (const VkBaseInStructure *)dst;
771:                 }
772:                 prev_struct = (VkBaseInStructure *)dst;
773:                 dst += loader_aligned_size(struct_type_info[i].size);
774:                 pnext = base.pNext;
775:                 break;
776:             }
777:         }
778:     }
779:     if (pAllocator) {
780:         icd_surface->callbacks_valid = true;
781:         icd_surface->callbacks = *pAllocator;
782:     }
783: 
784:     return VK_SUCCESS;
785: }
